const BAD_KEYS=new Set(['__proto__','constructor','prototype']);
function cleanList(x,min,max){return Array.isArray(x)?[...new Set(x.filter(n=>Number.isInteger(n)&&n>=min&&n<=max))].sort((a,b)=>a-b):[]}
function cleanStrings(o){let r={};if(o&&typeof o==='object'&&!Array.isArray(o))for(let [k,v] of Object.entries(o)){if(BAD_KEYS.has(k)||Object.keys(r).length>=80)continue;if(typeof v==='string'&&v.length<=20000)r[k]=v;else if(Array.isArray(v)&&v.length<=50&&v.every(x=>typeof x==='string'&&x.length<=500))r[k]=v}return r}
// True when nothing has been entered anywhere in Stead on this device.
function isBlank(x){return !Object.values(x.answers).some(v=>Array.isArray(v)?v.length:v)&&!x.reviewed.length&&!x.children.length&&!['before','after'].some(p=>x[p].properties.length||x[p].items.length||x[p].transfers.length)&&!x.journey.done.length&&!x.journey.env.length&&!x.journey.conf.length&&!Object.keys(x.formA).length&&!Object.keys(x.order).length}
// Ticks from the earlier stead.mobile page, on the same site, carry over once.
function fromMobile(m){if(!m||typeof m!=='object')return null;let keys=o=>Array.isArray(o)?o:Object.keys(o||{}).filter(k=>o[k]).map(Number);return {done:cleanList(keys(m.steps??m.stepsDone),1,14),env:cleanList(keys(m.env??m.envelopeTicked),0,6),conf:cleanList(keys(m.conf??m.beforeFilingTicked),0,5),date:typeof(m.co??m.conditionalOrderDate)==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(m.co??m.conditionalOrderDate)?(m.co??m.conditionalOrderDate):''}}
function withMobile(v,m){if(!m)return v;v.journey={done:m.done,env:m.env,conf:m.conf};if(m.date&&!v.answers.conditional)v.answers.conditional=m.date;return v}
function load(){for(const k of [KEY,OLD_KEY]){try{const raw=localStorage.getItem(k);if(raw){let v=validate(JSON.parse(raw));if(k===KEY&&isBlank(v)&&localStorage.getItem(OLD_KEY))continue;if(k===OLD_KEY)v.step='home';if(!v.journey.done.length&&!v.journey.env.length&&!v.journey.conf.length){try{v=withMobile(v,fromMobile(JSON.parse(localStorage.getItem(MOBILE_KEY))))}catch{}}return v}}catch{}}let v=empty();try{v=withMobile(v,fromMobile(JSON.parse(localStorage.getItem(MOBILE_KEY))))}catch{}return v}
