const monthly=(v,f='monthly')=>Math.round(pennies(v)*({monthly:1,weekly:52/12,fortnightly:26/12,'four-weekly':13/12,yearly:1/12}[f]||1));
const cats=[['capital','B','Savings & other assets','Bank balances, savings, investments, ISAs and other capital. Enter only each person’s share.','wallet'],['debt','D','Loans & other debts','Credit cards, loans and overdrafts. Exclude mortgages already deducted from a property.'],['pension','F','Pension pots','Use the cash equivalent valuation of each pension, rather than an annual retirement income.'],['ppf','G','Pension Protection Fund','Enter the capital valuation of PPF compensation, if applicable.'],['earnings','A','Take-home pay','Pay after tax and National Insurance. For self-employment, use an average from the most recent HMRC tax statement.'],['benefits','B','Benefits','Include state benefits and child benefit.'],['pensionIncome','C','Pension income','Regular pension income and PPF compensation payments.'],['interest','D','Bank interest','Interest received from bank accounts.'],['otherIncome','E','Other income','For example, trust fund or investment income.'],['received','J','Maintenance from someone else','Child maintenance received from someone outside these proceedings.'],['paid','K','Maintenance to someone else','Child or spousal maintenance paid to someone outside these proceedings. Enter a positive amount; we deduct it.']];
function allocation(net,shares){let raw=shares.map(v=>Math.abs(net)*v/100),values=raw.map(Math.floor),left=Math.abs(net)-values.reduce((a,b)=>a+b,0);let order=raw.map((v,i)=>({i,f:v-values[i]})).sort((a,b)=>b.f-a.f||a.i-b.i);for(let j=0;j<left;j++)values[order[j%3].i]++;return values.map(v=>v*Math.sign(net))}
function capital(s,p){let prop=s.properties.map(x=>allocation(pennies(x.value)-pennies(x.mortgage),[Number(x.a||0),Number(x.b||0),100-Number(x.a||0)-Number(x.b||0)])[p]);let sum=k=>s.items.filter(x=>x.kind===k&&x.person===p).reduce((a,x)=>a+pennies(x.amount),0);let A=prop.reduce((a,b)=>a+b,0),B=sum('capital'),C=A+B,D=sum('debt'),E=C-D,F=sum('pension'),G=sum('ppf');return {A,B,C,D,E,F,G,H:E+F+G,properties:prop}}
function income(s,p){let sum=k=>s.items.filter(x=>x.kind===k&&x.person===p).reduce((a,x)=>a+monthly(x.amount,x.frequency),0);let t=k=>s.transfers.filter(x=>x.kind===k).reduce((a,x)=>a+(p===Number(x.from)?-1:p===1-Number(x.from)?1:0)*monthly(x.amount,x.frequency),0);let A=sum('earnings'),B=sum('benefits'),C=sum('pensionIncome'),D=sum('interest'),E=sum('otherIncome'),F=A+B+C+D+E,G=t('child'),H=t('spousal'),I=G+H,J=sum('received'),K=-sum('paid'),L=J+K;return {A,B,C,D,E,F,G,H,I,J,K,L,M:F+I+L}}
